<script setup lang="ts">
import { computed } from 'vue';
import { FolderIcon, MessageSquareIcon } from 'lucide-vue-next';
import { lazyStrings } from '@/strings';
import RelativeTime from './RelativeTime.vue';
import type { ChatSummary } from '@/01-models/types';


const props = defineProps<{
  chat: ChatSummary & { accessedAt: number },
  groupName?: string,
  isSelected: boolean,
  activePane: 'results' | 'preview',
}>();

const timeFormatter = new Intl.DateTimeFormat(undefined, {
  month: 'short',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
});

function formatTime({ timestamp }: { timestamp: number }) {
  return timeFormatter.format(new Date(timestamp));
}

// Optimization: Pre-calculate classes to avoid complex logic in template
const containerClasses = computed(() => {
  if (!props.isSelected) {
    return "group flex flex-col p-2.5 rounded-xl cursor-pointer transition-[background-color,border-color,opacity] duration-150 border border-transparent hover:bg-gray-50 dark:hover:bg-gray-800/50";
  }

  const pane = props.activePane;
  switch (pane) {
  case 'results':
    return "group flex flex-col p-2.5 rounded-xl cursor-pointer transition-[background-color,border-color,opacity] duration-150 border border-transparent bg-blue-50 dark:bg-blue-900/30 border-blue-100 dark:border-blue-800 shadow-sm";
  case 'preview':
    return "group flex flex-col p-2.5 rounded-xl cursor-pointer transition-[background-color,border-color,opacity] duration-150 border border-transparent bg-gray-50 dark:bg-gray-800 border-gray-100 dark:border-gray-700 opacity-80";
  default: {
    const _ex: never = pane;
    throw new Error(`Unhandled pane: ${_ex}`);
  }
  }
});

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/69d3f89da3142837a4bf41b7a4d41941850c442adf8f9f43ef7bb05b3728dd83.js";
import "virtual:naidan-tailwind-css-module/6f506a4c0f543a091de5b53b381e587a6ba1c3c266800941cf9d0348e2f5ed30.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/ed434c08eb79158edc1aa000ec67e2dd3ec8116ce25385d9b382150312b39229.js";
</script>

<template>
  <div :tw-class="twClasses(containerClasses)">
    <div tw-class="flex items-center justify-between gap-3">
      <div tw-class="p-2 bg-gray-100 dark:bg-gray-800 rounded-lg shrink-0">
        <MessageSquareIcon :tw-class="['w-4 h-4', isSelected ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400']" />
      </div>
      <div tw-class="flex flex-col flex-1 overflow-hidden">
        <div tw-class="flex items-center justify-between gap-2">
          <div tw-class="flex flex-col overflow-hidden">
            <span tw-class="font-bold text-sm truncate text-gray-900 dark:text-gray-100">{{ chat.title || lazyStrings.SHARED__new_chat() }}</span>
            <span v-if="groupName" tw-class="text-[10px] text-gray-400 truncate flex items-center gap-1">
              <FolderIcon tw-class="w-2.5 h-2.5 opacity-50 text-blue-500" />
              <span>{{ groupName }}</span>
            </span>
            <span tw-class="text-[10px] text-gray-400 truncate opacity-60">
              <RelativeTime :timestamp="chat.accessedAt" prefix="Accessed " />
            </span>
          </div>
          <span tw-class="text-[10px] text-gray-400 shrink-0">{{ formatTime({ timestamp: chat.accessedAt }) }}</span>
        </div>
      </div>
    </div>
  </div>
</template>
